package com.progressly.notification.common;
import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e,HttpServletRequest r){var errors=e.getBindingResult().getFieldErrors().stream().map(x->Map.of("field",x.getField(),"message",x.getDefaultMessage()==null?"Invalid value":x.getDefaultMessage())).toList();return body(400,"VALIDATION_ERROR","Invalid request",r.getRequestURI(),errors);} @ExceptionHandler(ResponseStatusException.class) ResponseEntity<?> status(ResponseStatusException e,HttpServletRequest r){return body(e.getStatusCode().value(),"REQUEST_FAILED",e.getReason(),r.getRequestURI(),java.util.List.of());} @ExceptionHandler(Exception.class) ResponseEntity<?> unexpected(Exception e,HttpServletRequest r){return body(500,"INTERNAL_ERROR","An unexpected error occurred",r.getRequestURI(),java.util.List.of());} private ResponseEntity<?> body(int s,String e,String m,String p,Object d){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s,e,m,p,d));} public record ErrorResponse(Instant timestamp,int status,String error,String message,String path,Object details){} }
